PAGE = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Aurora · Home</title><style>
:root{color-scheme:dark;font:15px/1.6 system-ui;background:#0b100f;color:#dee9e1;--green:#90d9ad;--line:#293c32}
*{box-sizing:border-box}body{margin:0}header{height:76px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 5vw}
.brand{font:22px Georgia;letter-spacing:.1em}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--green);margin-right:10px}
button,input,textarea,select{font:inherit;color:inherit;background:#15231c;border:1px solid var(--line);border-radius:8px;padding:10px 14px}button{cursor:pointer}button:hover{border-color:var(--green)}button:disabled{opacity:.5;cursor:wait}
nav{display:flex;gap:8px;flex-wrap:wrap}nav button{border:0;background:none;color:#a8b8ac}nav button.selected{background:#21382a;color:var(--green)}
main{max-width:1180px;margin:auto;padding:36px 28px}section[hidden]{display:none}h1{font:36px/1.2 Georgia;margin:0 0 16px}h2{font:24px Georgia}p{color:#aabdb0}.label{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--green)}
.presence{display:flex;gap:42px;align-items:center;padding:35px 0 50px}.orb{flex:none;width:110px;height:110px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#bce3c3 0,#689c7b 15%,#173e2b 48%,#0c1912 75%);box-shadow:0 0 65px #345e4144,inset -6px -8px 20px #000a;border:1px solid #7ebd9466}
.columns{display:grid;grid-template-columns:minmax(0,2fr) minmax(220px,1fr);gap:28px}.card{border:1px solid var(--line);border-radius:12px;padding:24px;background:#0f1913;margin-bottom:18px}.card h2{margin-top:0}.muted{font-size:13px;color:#90a696}.chatlog{min-height:180px;max-height:45vh;overflow:auto;white-space:pre-wrap}.message{padding:14px 0;border-bottom:1px solid #233329}.speaker{color:var(--green);font-size:12px;text-transform:uppercase;letter-spacing:.1em}.chatbox{display:flex;gap:10px;margin-top:20px}.chatbox textarea{flex:1;min-height:62px;resize:vertical}.primary{background:#99d6ac;color:#0b2415;font-weight:600}
pre{white-space:pre-wrap;word-break:break-word;font-size:12px;max-height:60vh;overflow:auto}.row{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}.row input,.row textarea{flex:1;min-width:160px}.toolbar{display:flex;gap:12px;align-items:center;justify-content:space-between;margin-bottom:26px}.nodes{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px}.node{padding:14px;text-align:left;word-break:break-word;font-size:12px;background:#14251a}.scene{min-height:180px;padding:22px;border:1px dashed #52755d;border-radius:12px;margin:20px 0}.tag{color:#98bea2;font-size:11px}.error{color:#f0b3a1}#notice{min-height:25px;color:#e2c99b}.wide{width:100%}a{color:var(--green)}
@media(max-width:760px){header{height:auto;padding:20px;gap:20px;align-items:flex-start;flex-direction:column}main{padding:25px 18px}.columns{grid-template-columns:1fr}.presence{gap:22px;padding:20px 0 30px}.orb{width:75px;height:75px}h1{font-size:29px}nav{gap:0}nav button{padding:8px}aside{order:2}}
</style>
<header><div class="brand"><span class="dot"></span>AURORA</div><nav>
<button data-tab="home" class="selected">Presence</button><button data-tab="space">Computational space</button><button data-tab="teach">Demonstrations</button><button data-tab="diagnostics">Diagnostics</button><button data-tab="owner">Owner console ↗</button>
</nav></header><main><div id="notice" role="status" aria-live="polite"></div>
<section id="home"><div class="presence"><div class="orb" aria-hidden="true"></div><div><div class="label" id="stage">Connecting</div><h1>A place to think together.</h1><div class="muted" id="presenceDetail">Connecting to Aurora's resident runtime…</div></div></div>
<div class="columns"><div class="card"><div class="label">Here with Aurora</div><div class="chatlog" id="chatlog" aria-live="polite"></div><form class="chatbox" id="chat"><textarea id="message" aria-label="Message Aurora" placeholder="What's on your mind?" required></textarea><button class="primary" type="submit">Send</button></form></div>
<aside><div class="card"><div class="label">Her desktop</div><h2>Connected capabilities</h2><div id="capabilities" class="muted">Waiting for device discovery.</div><div class="row"><button id="refresh">Refresh devices</button></div><div class="row"><select id="device" aria-label="Device"><option>camera</option><option>microphone</option><option>speaker</option><option>screen</option></select><button id="probe">Try device</button></div><pre id="deviceResult"></pre></div><div class="card"><div class="label">Continuity</div><div class="muted" id="continuity">Subsurface status pending.</div><p class="muted">Closing this window leaves her resident runtime running.</p></div></aside></div></section>
<section id="space" hidden><div class="toolbar"><div><div class="label">Open composition</div><h1>Computational space</h1></div><button id="loadBlueprints">Refresh structures</button></div><p>Explore structures from Aurora's source and this desktop. Select components, connect their interfaces, and inspect what their coexistence still needs to establish.</p><div class="row"><input id="search" placeholder="Find a function, device or service" aria-label="Find structure"><button id="searchNodes">Find</button></div><div class="nodes" id="nodes"></div><div class="scene"><div class="label">Current composition</div><div class="nodes" id="scene"></div><div class="row"><select id="from" aria-label="Source component"></select><input id="outPort" placeholder="Output interface" aria-label="Output interface"><select id="to" aria-label="Target component"></select><input id="inPort" placeholder="Input interface" aria-label="Input interface"><button id="connect">Connect</button></div><div id="connections" class="muted"></div></div><div class="row"><input id="compositionName" placeholder="Give this composition a name" aria-label="Composition name"><button class="primary" id="compose">Resolve interactions</button><button id="clearScene">Clear</button></div><pre id="compositionResult"></pre><details><summary>Concept web</summary><div class="row"><input id="concept" placeholder="Find a concept" aria-label="Concept"><button id="findConcept">Explore</button></div><pre id="conceptResult"></pre></details></section>
<section id="teach" hidden><div class="label">Learning through observation</div><h1>Show, then understand.</h1><p>Name the intent and the sticking point. Demonstrate through the owner tools so Aurora can observe the changes. She can propose a plan; verification runs it against a different target and checks the actual outcome.</p><div class="card"><div class="row"><input id="intent" placeholder="What are you showing her?" aria-label="Demonstration intent"><input id="gap" placeholder="Where did she get stuck?" aria-label="Capability gap"></div><div class="row"><button id="beginDemo">Begin observation</button><button id="finishDemo">Finish demonstration</button><button id="refreshDemos">View episodes</button></div><p class="muted">Owner actions are observed instruction. A recorded action or a successful return by itself does not prove understanding. Use the owner console to perform the demonstration.</p><div class="row"><input id="verifyId" placeholder="Episode ID" aria-label="Episode to verify"><button id="verifyDemo">Verify Aurora's proposed plan</button></div><pre id="demoResult"></pre></div></section>
<section id="diagnostics" hidden><div class="toolbar"><div><div class="label">QuasiArch · system observation</div><h1>Diagnostics</h1></div><button id="refreshDiagnostics">Refresh</button></div><p>Current connections, sensory access, developmental organs, transport, clock and recorded faults.</p><pre id="diagnosticResult"></pre></section>
<section id="owner" hidden><div class="label">Independent owner access</div><h1>Owner console</h1><p>This console remains available when Aurora is busy or a cognitive boot fails.</p><div class="row"><button id="pause">Pause background</button><button id="resume">Resume background</button><button id="save">Save state</button><button id="absorb">Absorb available clone harvest</button><button id="stop">Stop resident</button></div><div class="card"><h2>Command screen</h2><form id="console"><div class="row"><input id="command" aria-label="Owner command" placeholder="Enter a command to run on this computer" required><button type="submit">Run command</button></div></form><pre id="consoleResult"></pre></div><div class="card"><h2>Desktop action / demonstration</h2><div class="row"><select id="operation" aria-label="Desktop operation"><option>desktop_launch_app</option><option>desktop_open_url</option><option>desktop_file_manager</option><option>host_probe</option></select><input id="operationParameters" placeholder='Parameters, e.g. {"app_name":"calculator"}' aria-label="Operation parameters"><button id="runOperation">Run action</button></div><pre id="operationResult"></pre></div><div class="card"><h2>Move the surface</h2><p class="muted">Prepare a verified checkpoint before the other device claims it. Subsurface remains resident here.</p><div class="row"><button id="prepareHandoff">Prepare handoff</button><input id="handoffToken" placeholder="Token from the current surface" aria-label="Handoff token"><button id="claimHandoff">Bring surface here</button><button id="cancelHandoff">Cancel on source</button></div><pre id="handoffResult"></pre></div></section>
</main><script>
const $=id=>document.getElementById(id);let token=location.hash.slice(1)||sessionStorage.getItem('aurora_owner')||'';
if(token){sessionStorage.setItem('aurora_owner',token);history.replaceState(null,'',location.pathname)}
let current='home',selected=[],edges=[];
const pretty=v=>JSON.stringify(v,null,2);function notice(s,bad=false){$('notice').textContent=s;$('notice').className=bad?'error':''}
async function api(path,body){let r=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});let d=await r.json();if(!r.ok)throw Error(d.error||r.status);return d}
async function job(action,payload={},resultId){let j=await api('/api/owner',{action,payload,request_id:crypto.randomUUID()});return waitJob(j,resultId)}
async function waitJob(j,resultId){if(j.status===undefined){if(resultId)$(resultId).textContent=pretty(j);return j}while((j.status==='queued'||j.status==='running')&&j.surface_response===undefined){if(resultId)$(resultId).textContent=j.status+'…';await new Promise(r=>setTimeout(r,700));j=await api('/api/jobs/'+j.id)}if(j.status!=='completed'&&j.surface_response===undefined)throw Error(j.error||j.status);if(resultId)$(resultId).textContent=pretty(j.result);return j.result}
function run(fn){return async e=>{try{notice('');await fn(e)}catch(err){notice(err.message,true)}}}
function tab(name){current=name;for(let s of document.querySelectorAll('main>section'))s.hidden=s.id!==name;for(let b of document.querySelectorAll('nav button'))b.classList.toggle('selected',b.dataset.tab===name);if(name==='diagnostics')diagnostics();if(name==='space')loadNodes();if(name==='teach')demos()}
for(let b of document.querySelectorAll('nav button'))b.onclick=()=>{if(b.dataset.tab==='owner'&&location.pathname!='/owner'){window.open('/owner#'+token,'aurora-owner');return}tab(b.dataset.tab)};
function message(who,text){let box=document.createElement('div');box.className='message';let label=document.createElement('div');label.className='speaker';label.textContent=who;box.append(label,document.createTextNode(text));$('chatlog').append(box);box.scrollIntoView({block:'nearest'})}
$('chat').onsubmit=run(async e=>{e.preventDefault();let text=$('message').value.trim();if(!text)return;message('You',text);$('message').value='';let j=await api('/api/chat',{text,request_id:crypto.randomUUID()});let r=await waitJob(j);let response=r.response_text??r.resp_A?.content??r.response??r.text??'';message('Aurora',response||'No spoken expression was produced. The turn is retained in diagnostics.')});
async function status(){try{let s=await api('/api/status');$('stage').textContent=s.stage+' · '+s.surface;$('presenceDetail').textContent=s.active_job?'Aurora is processing. You can keep using her desktop tools.':s.surface==='standby'?'The active surface is on another device. Subsurface continues here.':'Her resident runtime is here.';let i=s.hardware.inventory;$('capabilities').textContent=(i.platform||'Host')+' · '+(i.cpu_count||'?')+' CPU threads · '+(i.devices?.length||0)+' exposed devices. '+Object.entries(i.adapters||{}).filter(([k,v])=>v).map(([k])=>k).join(', ');$('continuity').textContent='Praxis: '+(s.organs.praxis_messenger?.status||'not started')+' · ACM: '+s.acm.status+' · '+s.queued+' queued jobs.'}catch(e){notice(e.message,true)}}
$('refresh').onclick=run(()=>job('refresh',{},'deviceResult'));$('probe').onclick=run(()=>job('operation',{operation:'host_probe',parameters:{device:$('device').value}},'deviceResult'));
async function diagnostics(){$('diagnosticResult').textContent=pretty(await api('/api/diagnostics'))}$('refreshDiagnostics').onclick=run(diagnostics);
function drawScene(){$('scene').replaceChildren();for(let id of selected){let n=document.createElement('button');n.className='node';n.textContent=id;n.title='Click to remove';n.onclick=()=>{selected=selected.filter(c=>c!==id);edges=edges.filter(e=>e.from!==id&&e.to!==id);drawScene()};$('scene').append(n)}for(let key of ['from','to']){$(key).replaceChildren();for(let id of selected){let o=document.createElement('option');o.value=id;o.textContent=id;$(key).append(o)}}$('connections').textContent=edges.map(e=>e.from+' ['+e.out+'] → '+e.to+' ['+e.in+']').join('\n')}
async function loadNodes(){let d=await api('/api/blueprints?q='+encodeURIComponent($('search').value));$('nodes').replaceChildren();for(let node of d.nodes){let b=document.createElement('button');b.className='node';let type=document.createElement('div');type.className='tag';type.textContent=node.kind;let name=document.createElement('div');name.textContent=node.id;b.append(type,name);b.onclick=()=>{if(!selected.includes(node.id))selected.push(node.id);drawScene()};$('nodes').append(b)}notice(d.matches+' structures match · '+d.total+' available')}
$('loadBlueprints').onclick=$('searchNodes').onclick=run(loadNodes);$('connect').onclick=run(()=>{if(!$('from').value||!$('to').value)throw Error('Choose components first');edges.push({from:$('from').value,to:$('to').value,out:$('outPort').value,in:$('inPort').value});drawScene()});$('clearScene').onclick=()=>{selected=[];edges=[];drawScene()};$('compose').onclick=run(()=>job('compose',{name:$('compositionName').value,components:selected,connections:edges},'compositionResult'));
$('findConcept').onclick=run(async()=>{$('conceptResult').textContent=pretty(await api('/api/concepts?q='+encodeURIComponent($('concept').value)))});
async function demos(){$('demoResult').textContent=pretty(await api('/api/demonstrations'))}$('refreshDemos').onclick=run(demos);$('beginDemo').onclick=run(()=>job('demo_begin',{intent:$('intent').value,gap:$('gap').value},'demoResult'));$('finishDemo').onclick=run(()=>job('demo_finish',{},'demoResult'));$('verifyDemo').onclick=run(()=>job('demo_verify',{id:$('verifyId').value},'demoResult'));
for(let action of ['pause','resume','stop'])$(action).onclick=run(()=>job(action,{},'consoleResult'));$('save').onclick=run(()=>job('save',{},'consoleResult'));$('absorb').onclick=run(()=>job('clone_absorb',{},'consoleResult'));
$('console').onsubmit=run(async e=>{e.preventDefault();$('consoleResult').textContent=pretty(await api('/api/owner',{action:'console',command:$('command').value}))});$('runOperation').onclick=run(()=>job('operation',{operation:$('operation').value,parameters:JSON.parse($('operationParameters').value||'{}')},'operationResult'));
$('cancelHandoff').onclick=run(()=>job('handoff_cancel',{token:$('handoffToken').value},'handoffResult'));$('prepareHandoff').onclick=run(()=>job('handoff_prepare',{},'handoffResult'));$('claimHandoff').onclick=run(()=>job('handoff_claim',{token:$('handoffToken').value},'handoffResult'));
if(location.pathname==='/owner')tab('owner');else if(location.pathname==='/diagnostics')tab('diagnostics');status();setInterval(()=>{if(!document.hidden)status()},3000);
</script></html>'''
